/**
 * Full-frame gold border: a strong outer rule, a hairline inner rule, and deliberately
 * unequal corners (rich flourishes top-left and bottom-right, small buds elsewhere).
 */
export const GoldFrame: React.FC<{
  width?: number;
  height?: number;
  draw?: number;
  inset?: number;
  style?: React.CSSProperties;
}> = ({ width = 1080, height = 1920, draw = 1, inset = 36, style }) => {
  const rules = interpolate(draw, [0, 0.6], [0, 1], { extrapolateRight: "clamp" });
  const grow = interpolate(draw, [0.4, 1], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const outerLen = 2 * (width + height);
  const i2 = inset + 12;
  return (
    <svg
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      style={{ position: "absolute", inset: 0, pointerEvents: "none", ...style }}
    >
      <g fill="none" stroke="url(#foil)">
        <rect
          x={inset}
          y={inset}
          width={width - inset * 2}
          height={height - inset * 2}
          strokeWidth={2.4}
          strokeDasharray={outerLen}
          strokeDashoffset={outerLen * (1 - rules)}
        />
        <rect
          x={i2}
          y={i2}
          width={width - i2 * 2}
          height={height - i2 * 2}
          strokeWidth={0.9}
          strokeDasharray={outerLen}
          strokeDashoffset={outerLen * (1 - rules)}
        />
      </g>
      <g transform={`translate(${i2 + 4} ${i2 + 4})`}>
        <Flourish grow={grow} />
      </g>
      <g transform={`translate(${width - i2 - 4} ${height - i2 - 4}) rotate(180)`}>
        <Flourish grow={grow} />
      </g>
      <g transform={`translate(${width - i2 - 4} ${i2 + 4}) scale(-1 1)`}>
        <SmallCorner grow={grow} />
      </g>
      <g transform={`translate(${i2 + 4} ${height - i2 - 4}) scale(1 -1)`}>
        <SmallCorner grow={grow} />
      </g>
    </svg>
  );
};
